function applyCourseProfile(hit,role=null){
 const direct=DIRECT_COURSE_PROFILES[hit?.id]||null, prof=role||direct;
 u.profile.subjectWeights=prof?.subjectWeights?{...prof.subjectWeights}:null;u.profile.subjectLabels=prof?.subjectLabels?{...prof.subjectLabels}:{};u.profile.recommendedStart=prof?.recommendedStart||'';u.profile.role=prof?.label||prof?.role||'';u.profile.roleId=prof?.id||'';u.profile.specificSubjectLabel=prof?.specificLabel||'';u.profile.examStructure=prof?.examStructure||roleProfileForCourse(hit)?.structure||'';u.profile.examStructureSource=prof?.examSource||roleProfileForCourse(hit)?.source||hit?.source_url||'';
}
function courseQuestionFormat(){return u?.profile?.questionFormat||'';}
function formattedTrainingQuestions(base){
 const fmt=courseQuestionFormat(),qs=Array.isArray(base?.questions)?base.questions:[];
 if(fmt==='ce')return qs.map((q,i)=>{const correct=Number(q.ok)||0,useCorrect=i%2===0,shown=useCorrect?correct:(correct===0?1:0),statement=(q.q||'').replace(/[?:\s]+$/,'');return {...q,q:`Julgue o item: ${statement} — ${q.choices[shown]}.`,choices:['Certo','Errado'],ok:useCorrect?0:1,why:useCorrect?q.why:`O item está errado. ${q.why}`};});
 if(fmt==='abcde')return qs.map(q=>q.choices?.length===4?{...q,choices:[...q.choices,'Todas as alternativas anteriores estão corretas.']}:q);
 if(fmt==='abcd')return qs.map(q=>q.choices?.length>4?{...q,choices:q.choices.slice(0,4),ok:Math.min(Number(q.ok)||0,3)}:q);
 return qs;
}
