function recordQuestionPerformance(source,qidx,ok){const d=ensureDay(),key=`${d.index}:${currentSubjectKey()}:${source}:${qidx}`;if(d.sessionSeen[key])return false;d.sessionSeen[key]=1;updatePerf(ok);const st=d.sessionStats||(d.sessionStats={correct:0,total:0,streak:0,bestStreak:0});st.total++;if(ok){st.correct++;st.streak++;st.bestStreak=Math.max(st.bestStreak||0,st.streak);}else st.streak=0;aesave();return true;}
function performanceSnapshot(){const d=ensureDay(),k=currentSubjectKey(),p=ae.performance[k]||{correct:0,total:0},st=d.sessionStats||{correct:0,total:0,streak:0,bestStreak:0};return {subject:p.total?Math.round(p.correct/p.total*100):0,today:st.total?Math.round(st.correct/st.total*100):0,streak:st.streak||0,best:st.bestStreak||0,correct:p.correct,total:p.total};}
function encouragementText(ok,snap){if(!ok)return snap.today>=70?'Você está mantendo um bom aproveitamento. Corrija esta agora e siga o ritmo.':'Esse erro virou revisão imediatamente — é exatamente assim que o sistema fortalece sua memória.';if(snap.streak>=4)return `🔥 ${snap.streak} acertos seguidos! Você entrou em ritmo forte.`;if(snap.subject>=80)return '🚀 Excelente. Seu domínio desta matéria já está em nível alto nesta sessão.';if(snap.subject>=60)return '👏 Muito bom. Você está consolidando o assunto — continue a sequência.';return '🎉 Parabéns! Mais um acerto registrado. Continue enquanto a memória está ativa.';}
function buildQuestionFeedback(sub,idx,ok,compact=false){const q=sub.questions[idx],snap=performanceSnapshot(),k=currentSubjectKey(),legal=isLegalSubjectKey(k),meta=legalQuestionMeta(k,idx),heading=ok?'🎉 Parabéns! Você acertou.':'❌ Resposta incorreta — vamos fixar a correta.';const stats=`<div class="performance-strip"><div><strong>${snap.subject}%</strong><span>${sub.name}</span></div><div><strong>${snap.today}%</strong><span>hoje</span></div><div><strong>${snap.streak}</strong><span>sequência</span></div></div><div class="accuracy-bar"><i style="width:${snap.today}%"></i></div>`;let detail=`<div class="answer-feedback ${ok?'feedback-ok':'feedback-bad'}"><b>${ok?'Por que está certa':'Resposta correta'}:</b> ${ok?q.why:`${q.choices[q.ok]}<br><br>${q.why}`}</div>`;if(legal&&meta){detail+=`<div class="legal-feedback-grid"><div class="legal-box"><span>⚖️ FUNDAMENTO</span><b>${meta.basis}</b></div><div class="legal-box"><span>🧠 EM LINGUAGEM SIMPLES</span><p>${meta.simple}</p></div><div class="legal-box"><span>🎯 COMO A BANCA COBRA</span><p>${meta.bank}</p></div><div class="legal-box"><span>⚠️ PEGADINHA / GATILHO</span><p>${meta.trap}</p></div></div>`;}else{detail+=`<div class="nonlegal-feedback-grid"><div class="memory-tip"><span>🧠 COMO PENSAR</span><p>${q.why}</p></div><div class="memory-tip"><span>💡 GATILHO DE MEMÓRIA</span><p>${sub.flash?.[idx]?.[1]||sub.keywords?.slice(0,3).join(' • ')||'Explique a regra com suas próprias palavras antes de seguir.'}</p></div></div>`;}return `<div class="instant-result ${ok?'instant-ok':'instant-bad'}"><h3>${heading}</h3><p class="motivation-line">${encouragementText(ok,snap)}</p>${stats}${compact?'':detail}${compact&&ok?`<div class="mini-explain">${q.why}</div>`:compact&&!ok?detail:''}</div>`;}
window.buildQuestionFeedback=buildQuestionFeedback;
window.recordQuestionPerformance=recordQuestionPerformance;

